class LanguageOption {
  final String code;
  final String name;
  final String nativeName;
  final String flag;
  final String currencySymbol;
  final String currencyCode;

  const LanguageOption({
    required this.code,
    required this.name,
    required this.nativeName,
    required this.flag,
    required this.currencySymbol,
    required this.currencyCode,
  });
}

class VipPricingInfo {
  final String weeklyPrice;
  final String weeklyPeriod;
  final String monthlyPrice;
  final String monthlyPeriod;
  final String yearlyPrice;
  final String yearlyPeriod;
  final String yearlyMonthlyEquivalent;
  final String lifetimePrice;
  final String lifetimePeriod;
  final String currencySymbol;
  final String saveBadge;

  const VipPricingInfo({
    required this.weeklyPrice,
    required this.weeklyPeriod,
    required this.monthlyPrice,
    required this.monthlyPeriod,
    required this.yearlyPrice,
    required this.yearlyPeriod,
    required this.yearlyMonthlyEquivalent,
    required this.lifetimePrice,
    required this.lifetimePeriod,
    required this.currencySymbol,
    required this.saveBadge,
  });
}

