  static VipPricingInfo get currentPricing =>
      _pricingMap[currentLocale] ?? _pricingMap['en']!;

  /// Initialize localization by checking saved preference or device system locale
  static Future<void> init() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final savedCode = prefs.getString(_prefKey);

      if (savedCode != null && _isSupported(savedCode)) {
        localeNotifier.value = savedCode;
        return;
      }

      // Detect system locale
      final deviceLocale = ui.PlatformDispatcher.instance.locale;
      final fullTag =
          '${deviceLocale.languageCode}_${deviceLocale.countryCode}';
      final langCode = deviceLocale.languageCode;

      if (_isSupported(fullTag)) {
        localeNotifier.value = fullTag;
      } else if (_isSupported(langCode)) {
        localeNotifier.value = langCode;
      } else {
        // Fallback default: English
        localeNotifier.value = 'en';
      }
    } catch (e) {
      localeNotifier.value = 'en';
    }
  }

  static bool _isSupported(String code) {
    return supportedLanguages.any((lang) => lang.code == code);
  }

  /// Change active language and persist to disk
  static Future<void> setLanguage(String code) async {
    if (!_isSupported(code)) return;
    localeNotifier.value = code;
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(_prefKey, code);
    } catch (_) {}
  }

  static LanguageOption get currentLanguageOption {
    return supportedLanguages.firstWhere(
      (l) => l.code == currentLocale,
      orElse: () => supportedLanguages[1], // default en
    );
  }

  static LanguageOption getLanguageOption(String code) {
    return supportedLanguages.firstWhere(
      (l) => l.code == code,
      orElse: () => supportedLanguages.firstWhere(
        (l) => _baseLocaleCode(l.code) == _baseLocaleCode(code),
        orElse: () => supportedLanguages[0],
      ),
    );
  }

