  static String localizePresetCustomSectionTitle(String title) {
    final cleanTitle = title
        .replaceAll('🏆', '')
        .replaceAll('📜', '')
        .replaceAll('🎗', '')
        .replaceAll('📚', '')
        .replaceAll('🎯', '')
        .replaceAll('\u{FE0F}', '')
        .trim()
        .toLowerCase();
    const awardTitles = {
      'honors & awards',
      'awards & achievements',
      'ödüller & başarılar',
      'auszeichnungen & erfolge',
      'prix & récompenses',
      'premios y logros',
      'prêmios & conquistas',
      'premi & riconoscimenti',
      'onderscheidingen & prijzen',
      'nagrody i wyróżnienia',
      'награды и достижения',
      'الجوائز والإنجازات',
      'सम्मान और पुरस्कार',
      '荣誉与奖项',
      '受賞歴・実績',
      '수상 및 성과',
      'penghargaan & prestasi',
    };
    if (awardTitles.contains(cleanTitle)) {
      return getQuickCustomTitles().first;
    }
    return title;
  }

