  static String _canonicalLocaleKey(String locale) {
    final normalized = locale.replaceAll('-', '_');
    final parts = normalized.split('_');
    if (parts.length > 1) {
      return '${parts.first.toLowerCase()}_${parts[1].toUpperCase()}';
    }
    return normalized.toLowerCase();
  }

  static String _baseLocaleCode(String locale) {
    return locale.replaceAll('-', '_').split('_').first.toLowerCase();
  }

  static Map<String, String>? _dictionaryFor(String locale) {
    final canonical = _canonicalLocaleKey(locale);
    return _translations[canonical] ?? _translations[_baseLocaleCode(locale)];
  }

  static String? _overrideFor(String locale, String key) {
    final canonical = _canonicalLocaleKey(locale);
    final base = _baseLocaleCode(locale);
    return _translationOverrides[canonical]?[key] ??
        _translationOverrides[base]?[key];
  }

