    final text = values[key];
    if (text == null || index >= text.length) return null;
    return text[index];
  }

  /// Translate a key with fallback cascade
  static String tr(String rawKey) => trFor(currentLocale, rawKey);

  /// Translate a key for an explicit locale without changing app state.
  static String trFor(String locale, String rawKey) {
    final key = _keyAliases[rawKey] ?? rawKey;
    final aiMessage = CvAiMessages.lookup(locale, key);
    if (aiMessage != null) return aiMessage;
    final override = _overrideFor(locale, key);
    if (override != null) return override;

    final cvFieldText = _cvFieldTextFor(locale, key);
    if (cvFieldText != null) return cvFieldText;

    final cvSectionText = _cvSectionTextFor(locale, key);
    if (cvSectionText != null) return cvSectionText;

    final cvWideText = _cvWideTextFor(locale, key);
    if (cvWideText != null) return cvWideText;

    final converterText = _converterTextFor(locale, key);
    if (converterText != null) return converterText;

    final authText = _authTextFor(locale, key);
    if (authText != null) return authText;

    final scannerText = _scannerTextFor(locale, key);
    if (scannerText != null) return scannerText;

    final permText = _permissionTextFor(locale, key);
    if (permText != null) return permText;

    final subscriptionText = _subscriptionTextFor(locale, key);
    if (subscriptionText != null) return subscriptionText;

    final langDict = _dictionaryFor(locale);
    if (langDict != null && langDict.containsKey(key)) {
      return langDict[key]!;
    }
    // Fallback: If locale is regional e.g. pt_BR or es_MX, try base language
    final canonical = _canonicalLocaleKey(locale);
    if (canonical.contains('_')) {
      final base = _baseLocaleCode(canonical);
      final baseDict = _translations[base];
      if (baseDict != null && baseDict.containsKey(key)) {
        return baseDict[key]!;
      }
    }

    // Dynamic smart resolution for language levels and hints
    final lang = locale.toLowerCase();
    if (key == 'cv_ai_prompt_hint') {
      if (lang.startsWith('tr')) {
        return 'Yapay zeka ile CV’nizi en öne çıkararak seçilme olasılığınızı yükseltin';
